                if (rid) {
                    selected.push(rid);
                }
            }
        });
        var serialized = selected.join(',');
        if (hiddenField) {
            hiddenField.value = serialized;
        }
        try {
            if (selected.length > 0) {
                window.localStorage.setItem(storageKey, serialized);
